/** Pinned first study-input and admission-ledger schemas. The compact strings
  * mirror src/test/resources/eyes4s/study-input-v1.json and
  * admission-ledger-v1.json for portable JVM/JS tests; the JVM suite checks
  * the pretty-printed resource bytes.
  */
object StudyInputFixtures:
  /** The matched-control fixture as a typed study input; digest cebe7474ab5c2aec. */
  def matchedControl: StudyInput[StudyKey, Px] =
    def get[E, A](e: Either[E, A]): A = e.fold(x => throw new AssertionError(s"$x"), identity)
    val frame                         = get(Frame.screen("matched-control-display", 2, 2))
    StudyInput(
      Trials(
        MatchedControlFixtures.fixations
          .groupBy(r => StudyKey(r.participant, r.image, r.phase))
          .toVector
          .sortBy(_._1)
          .map { case (key, rows) =>
            val clock = ClockId(s"fixation-trial:${KeyDigest[StudyKey].digest(key).render}")
            val fixes = rows.sortBy(_.ordinal).map { row =>
              get(
                Event.Fixation.withoutDispersion(
                  get(
                    Interval.of(
                      clock,
                      Instant.micros(row.onsetMicros),
                      Instant.micros(row.onsetMicros + row.durationMicros)
                    )
                  ),
                  Pt[Px](row.x, row.y),
                  row.sampleCount
                )
              )
            }
            Trial(key, (), get(Scanpath.of(frame, clock, IArray.from(fixes))))
          }
      )
    )

  /** Header and raw records of the matched-control CSV, as the importer decodes them. */
  val header: Vector[String] = Vector(
    "participant",
    "image",
    "phase",
    "fixation",
    "x_px",
    "y_px",
    "onset_us",
    "duration_us",
    "sample_count"
  )
  val records: Vector[Vector[String]] = MatchedControlFixtures.fixations.map(r =>
    Vector(
      r.participant,
      r.image,
      r.phase,
      r.ordinal.toString,
      r.x.toString,
      r.y.toString,
      r.onsetMicros.toString,
      r.durationMicros.toString,
      r.sampleCount.toString
    )
  )

  /** The v1 ledger fixture imports these records: record 2 carries duration -1. */
  val refusedRecords: Vector[Vector[String]] =
    records.updated(0, records.head.updated(7, "-1"))

